'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostSameValue = require( '@stdlib/number/float64/base/assert/is-almost-same-value' );
var rffti = require( '@stdlib/fft/base/fftpack/rffti' );
var rfftf = require( './../lib' );


// FIXTURES //

var small = require( './fixtures/c/fftpack/small.json' );
var medium = require( './fixtures/c/fftpack/medium.json' );
var large = require( './fixtures/c/fftpack/large.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rfftf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( rfftf.length, 7, 'returns expected value' );
	t.end();
});

tape( 'the function returns a reference to the input array', function test( t ) {
	var out;
	var w;
	var N;
	var r;

	N = 4;
	r = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	w = new Float64Array( ( 2 * N ) + 34 );

	rffti( N, w, 1, 0 );
	out = rfftf( N, r, 1, 0, w, 1, 0 );

	t.strictEqual( out, r, 'same reference' );
	t.end();
});

tape( 'the function returns all zeros for a zero sequence', function test( t ) {
	var expected;
	var w;
	var N;
	var r;

	N = 4;
	r = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	expected = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	w = new Float64Array( ( 2 * N ) + 34 );

	rffti( N, w, 1, 0 );
	rfftf( N, r, 1, 0, w, 1, 0 );

	t.deepEqual( r, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns only a zero-frequency term for a constant sequence', function test( t ) {
	var expected;
	var w;
	var N;
	var r;

	N = 4;
	r = new Float64Array( [ 1.0, 1.0, 1.0, 1.0 ] );
	expected = new Float64Array( [ 4.0, 0.0, 0.0, 0.0 ] );
	w = new Float64Array( ( 2 * N ) + 34 );

	rffti( N, w, 1, 0 );
	rfftf( N, r, 1, 0, w, 1, 0 );

	t.deepEqual( r, expected, 'returns expected value' );
	t.end();
});

tape( 'the function computes the exact two-point real FFT', function test( t ) {
	var expected;
	var w;
	var N;
	var r;

	N = 2;
	r = new Float64Array( [ 3.0, -1.0 ] );

	// For [ a, b ], output is [ a+b, a-b ]...
	expected = new Float64Array( [ 2.0, 4.0 ] );
	w = new Float64Array( ( 2 * N ) + 34 );

	rffti( N, w, 1, 0 );
	rfftf( N, r, 1, 0, w, 1, 0 );

	t.deepEqual( r, expected, 'returns expected value' );
	t.end();
});

tape( 'the function computes a forward real-valued FFT (small sequence lengths)', function test( t ) {
	var expected;
	var lengths;
	var offsets;
	var input;
	var ulps;
	var off;
	var w;
	var y;
	var e;
	var N;
	var i;
	var k;
	var r;

	lengths = small.lengths;
	offsets = small.offsets;
	input = small.input;
	expected = small.expected;

	ulps = 20;
	for ( k = 0; k < lengths.length; k++ ) {
		N = lengths[ k ];
		off = offsets[ k ];
		r = new Float64Array( N );
		for ( i = 0; i < N; i++ ) {
			r[ i ] = input[ off + i ];
		}
		w = new Float64Array( ( 2 * N ) + 34 );

		rffti( N, w, 1, 0 );
		rfftf( N, r, 1, 0, w, 1, 0 );

		for ( i = 0; i < N; i++ ) {
			y = r[ i ];
			e = expected[ off + i ];
			t.strictEqual( isAlmostSameValue( y, e, ulps ), true, 'within tolerance. N: '+N+'. index: '+i+'. y: '+y+'. E: '+e+'.' );
		}
	}
	t.end();
});

