tape( 'the function leaves a length-one sequence unchanged', function test( t ) {
	var out;
	var N;
	var w;
	var r;

	N = 1;
	r = new Float64Array( [ 5.0 ] );
	w = new Float64Array( ( 2 * N ) + 34 );

	rffti( N, w, 1, 0 );
	out = rfftf( N, r, 1, 0, w, 1, 0 );
	t.strictEqual( out, r, 'same reference' );
	t.strictEqual( r[ 0 ], 5.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying a stride', function test( t ) {
	var expected;
	var w;
	var v;
	var i;
	var N;
	var r;

	N = 4;
	r = new Float64Array([
		1.0,   // 0
		-999.0,
		2.0,   // 1
		-999.0,
		3.0,   // 2
		-999.0,
		4.0,   // 3
		-999.0
	]);
	expected = new Float64Array([
		10.0,  // 0
		-999.0,
		-2.0,  // 1
		-999.0,
		2.0,   // 2
		-999.0,
		-2.0,  // 3
		-999.0
	]);

	w = new Float64Array( ( ( 2 * N ) + 34 ) * 2 );
	rffti( N, w, 2, 0 );
	rfftf( N, r, 2, 0, w, 2, 0 );

	for ( i = 0; i < r.length; i++ ) {
		v = r[ i ];
		t.strictEqual( isAlmostSameValue( v, expected[ i ], 1 ), true, 'within tolerance. index: '+i+'. y: '+v+'. E: '+expected[ i ]+'.' );
	}
	t.end();
});

tape( 'the function supports specifying a negative stride', function test( t ) {
	var expected;
	var w;
	var v;
	var i;
	var N;
	var r;

	N = 4;
	r = new Float64Array([
		4.0,   // 3
		-999.0,
		3.0,   // 2
		-999.0,
		2.0,   // 1
		-999.0,
		1.0    // 0
	]);
	expected = new Float64Array([
		-2.0,  // 3
		-999.0,
		2.0,   // 2
		-999.0,
		-2.0,  // 1
		-999.0,
		10.0   // 0
	]);

	w = new Float64Array( ( 2 * N ) + 34 );
	rffti( N, w, -1, w.length-1 );
	rfftf( N, r, -2, r.length-1, w, -1, w.length-1 );

	for ( i = 0; i < r.length; i++ ) {
		v = r[ i ];
		t.strictEqual( isAlmostSameValue( v, expected[ i ], 1 ), true, 'within tolerance. index: '+i+'. y: '+v+'. E: '+expected[ i ]+'.' );
	}
	t.end();
});

tape( 'the function supports an offset parameter', function test( t ) {
	var expected;
	var w;
	var v;
	var i;
	var N;
	var r;

	N = 4;
	r = new Float64Array([
		-999.0,
		1.0,   // 0
		-999.0,
		2.0,   // 1
		-999.0,
		3.0,   // 2
		-999.0,
		4.0,   // 3
		-999.0
	]);
	expected = new Float64Array([
		-999.0,
		10.0,  // 0
		-999.0,
		-2.0,  // 1
		-999.0,
		2.0,   // 2
		-999.0,
		-2.0,  // 3
		-999.0
	]);

	w = new Float64Array( 3 + ( ( ( 2 * N ) + 34 ) * 2 ) );
	rffti( N, w, 2, 3 );
	rfftf( N, r, 2, 1, w, 2, 3 );

	for ( i = 0; i < r.length; i++ ) {
		v = r[ i ];
		t.strictEqual( isAlmostSameValue( v, expected[ i ], 1 ), true, 'within tolerance. index: '+i+'. y: '+v+'. E: '+expected[ i ]+'.' );
	}
	t.end();
});
